//! Emits context facts from the pinned standard library, never runtime input.
fn ranges(values: impl Iterator<Item = char>) -> Vec<(char, char)> {
    let mut result: Vec<(char, char)> = Vec::new();
    for c in values {
        if let Some(last) = result.last_mut() {
            if last.1 as u32 + 1 == c as u32 {
                last.1 = c;
                continue;
            }
        }
        result.push((c, c));
    }
    result
}
fn main() {
    assert_eq!(char::UNICODE_VERSION, (17, 0, 0));
    let mut cased = Vec::new();
    let mut ignorable = Vec::new();
    for c in (0..=0x10ffff).filter_map(char::from_u32) {
        let effective_cased = format!("{c}Σ").to_lowercase().ends_with('ς');
        let cased_or_ignorable = format!("A{c}Σ").to_lowercase().ends_with('ς');
        if effective_cased {
            cased.push(c);
        } else if cased_or_ignorable {
            ignorable.push(c);
        }
    }
    println!(
        "// Generated by validation/emit-lowercase.rs with Unicode {:?} standard lowering.",
        char::UNICODE_VERSION
    );
    println!("// Context-cased excludes ignorable characters; the writer skips ignorable first.");
    for (name, values) in [("CASED", cased), ("IGNORABLE", ignorable)] {
        println!("pub(super) const {name}: &[(char, char)] = &[");
        for (a, b) in ranges(values.into_iter()) {
            println!("    ({a:?}, {b:?}),");
        }
        println!("];\n");
    }
}
